function recomputeLevels(seam: ISqlSeam): Observable<void> {
  const sql = `DELETE FROM "__host_demand_scan_span";\nINSERT OR IGNORE INTO "__host_demand_scan_span" ("identity_digest", "witness_digest", "path") SELECT ('identity|scan_span' || '|' || 'path' || ':' || 'text' || '=' || b0."path"), ('witness|scan_span' || '|' || 'path' || ':' || 'text' || '=' || b0."path"), b0."path" FROM "source_path" b0;\nDELETE FROM "host_span";\nINSERT OR IGNORE INTO "host_span" ("path", "at") SELECT b0."path", b1."at" FROM "source_path" b0, "__host_response_scan_span" b1 WHERE b1."path" = b0."path" AND b1."witness_digest" = ('witness|scan_span' || '|' || 'path' || ':' || 'text' || '=' || b0."path");\nDELETE FROM "host_start";\nINSERT OR IGNORE INTO "host_start" ("path", "start") SELECT b0."path", b1."start" FROM "host_span" b0, "__ref_span" b1 WHERE b1."__id" = b0."at"`;
  return seam.runner.executeMultiple(seam.db, sql);
}

function buildDeltas(before: Snapshot, after: Snapshot): ITickDeltas {
  const __host_demand_scan_span = multisetDiff(before.__host_demand_scan_span, after.__host_demand_scan_span);
  const __host_response_scan_span = multisetDiff(before.__host_response_scan_span, after.__host_response_scan_span);
  const host_span = multisetDiff(before.host_span, after.host_span);
  const host_start = multisetDiff(before.host_start, after.host_start);
  const source_path = multisetDiff(before.source_path, after.source_path);
  const span = multisetDiff(before.span, after.span);
  return {
    rels: [
      { rel: "__host_demand_scan_span", add: __host_demand_scan_span.add, del: __host_demand_scan_span.del },
      { rel: "__host_response_scan_span", add: __host_response_scan_span.add, del: __host_response_scan_span.del },
      { rel: "host_span", add: host_span.add, del: host_span.del },
      { rel: "host_start", add: host_start.add, del: host_start.del },
      { rel: "source_path", add: source_path.add, del: source_path.del },
      { rel: "span", add: span.add, del: span.del },
    ],
    carryPending: false,
  };
}

function runNaiveTick(seam: ISqlSeam, arrivals: IArrivalBatch): Observable<ITickDeltas> {
  return readSnapshot(seam).pipe(
    concatMap((before) => applyArrivals(seam, arrivals).pipe(map(() => before))),
    concatMap((before) => recomputeLevels(seam).pipe(map(() => before))),
    concatMap((before) => readSnapshot(seam).pipe(map((after) => buildDeltas(before, after)))),
  );
  // struct_host_output_schedule_answer_interned: no edge rules -- absorb arrivals, recompute levels, diff.
}

const INCREMENTAL_PROGRAM_SAFE = true;
const RECONCILE_EVERY_TICK = false;
const EMITTER_MODE = process.env.SPREFA_TSV2_EMITTER_MODE === "naive" ? "naive" : "incremental";

function runIncrementalTick(seam: ISqlSeam, arrivals: IArrivalBatch): Observable<ITickDeltas> {
  return IncrementalRuntime.prepareTick(seam, INCREMENTAL_RELATIONS).pipe(
    concatMap(() => IncrementalRuntime.applyArrivals(seam, arrivals, INCREMENTAL_RELATIONS)),
    concatMap(() => IncrementalRuntime.applyLevelsBeforeEdges(seam, INCREMENTAL_LEVEL_STATEMENTS, INCREMENTAL_RELATIONS)),
    concatMap(() => IncrementalRuntime.applyEdges(seam, INCREMENTAL_EDGE_STATEMENTS, INCREMENTAL_RELATIONS)),
    concatMap(() => of(undefined)),
    concatMap(() => of(undefined)),
    concatMap(() => IncrementalRuntime.recomputeLevelsAfterEdges(seam, INCREMENTAL_LEVEL_STATEMENTS, INCREMENTAL_RELATIONS, RECONCILE_EVERY_TICK)),
    concatMap(() => IncrementalRuntime.readBoundary(seam, INCREMENTAL_RELATIONS)),
    concatMap((rels) => IncrementalRuntime.promoteFrontiers(seam, INCREMENTAL_RELATIONS).pipe(
      map((carryPending): ITickDeltas => ({ rels, carryPending })),
    )),
  );
}

function runTickOnInternedArrivals(seam: ISqlSeam, arrivals: IArrivalBatch): Observable<ITickDeltas> {
  if (EMITTER_MODE === "naive" || !INCREMENTAL_PROGRAM_SAFE) {
    return runNaiveTick(seam, arrivals);
  }
  return runIncrementalTick(seam, arrivals);
}

function runTick(seam: ISqlSeam, arrivals: IArrivalBatch): Observable<ITickDeltas> {
  return StructPlane.intern(seam, STRUCT_TYPES, STRUCT_REF_COLUMNS, arrivals).pipe(
    concatMap((interned) => runTickOnInternedArrivals(seam, interned)),
  );
}

export const incrementalPlan: IIncrementalProgramPlan = {
  safe: INCREMENTAL_PROGRAM_SAFE,
  reconcileEveryTick: RECONCILE_EVERY_TICK,
  retractionGuard: "plain-count-acyclic",
  relations: INCREMENTAL_RELATIONS,
  edges: INCREMENTAL_EDGE_STATEMENTS,
  levels: INCREMENTAL_LEVEL_STATEMENTS,
};

export const program: IGenProgramWithBoot = {
  name: "struct_host_output_schedule_answer_interned",
  ddl,
  relColumns,
  arrivalTargets,
  boot,
  finalSelect,
  hostPlans,
  bindPlans,
  queryPlans,
  unsupportedExecution,
  tick: runTick,
};
